export const DEFAULT_PERSONA = "marcus";
export const getPersona = (id: string | undefined) => PERSONAS.find((p) => p.id === id);

// pn_as cookie: the persona the visitor is acting as. Not a security boundary (it's a demo
// switcher); scope is still enforced server-side for whichever persona is chosen.
export const PN_AS = "pn_as";
export const personaCookie = (id: string) => `${PN_AS}=${encodeURIComponent(id)}; Path=/; SameSite=Lax; Max-Age=2592000`;
export function personaFromCookieHeader(header: string | null | undefined): Persona {
  const raw = header?.split(/;\s*/).find((c) => c.startsWith(`${PN_AS}=`));
  return getPersona(raw ? decodeURIComponent(raw.slice(PN_AS.length + 1)) : undefined) ?? getPersona(DEFAULT_PERSONA)!;
}

// Role × module access (Settings → Roles shows this matrix). EntityDef.permissions narrows it
// per entity; registry.can() requires both. approve = may run approval actions in that module.
export type Access = "none" | "read" | "write" | "approve";
type Matrix = Record<Role, Partial<Record<ModuleKey, Access>>>;
const ALL = (a: Access): Record<ModuleKey, Access> =>
  ({ portfolio: a, leasing: a, residents: a, maintenance: a, communications: a, receivables: a, payables: a, accounting: a, owners: a, risk: a, intelligence: a, settings: a, platform: "none" });

export const PERMISSIONS: Matrix = {
  platform_admin: { ...ALL("read"), settings: "approve", platform: "approve", intelligence: "approve" },
  principal: { ...ALL("approve"), settings: "read" },
  regional_manager: { ...ALL("approve"), accounting: "read", settings: "read" },
  property_manager: { ...ALL("write"), payables: "read", accounting: "read", owners: "read", settings: "none", intelligence: "approve" },
  leasing_agent: { portfolio: "read", leasing: "write", residents: "read", communications: "write", intelligence: "read" },
  broker: { portfolio: "read", leasing: "approve", residents: "read", communications: "write", owners: "approve", risk: "read", intelligence: "approve" },
  accountant: { portfolio: "read", residents: "read", receivables: "approve", payables: "approve", accounting: "approve", owners: "approve", risk: "read", intelligence: "approve", maintenance: "read" },
  maintenance_supervisor: { portfolio: "read", maintenance: "approve", residents: "read", communications: "write", risk: "write", intelligence: "approve", payables: "read" },
  admin: { ...ALL("read"), settings: "approve", intelligence: "read" },
  // Portals reach their own records only (scope "self"); their pages live under /portal.
  owner: { portfolio: "read", owners: "approve", accounting: "read", maintenance: "read", communications: "write" },
  resident: { residents: "write", receivables: "write", maintenance: "write", communications: "write" },
  vendor: { maintenance: "write", payables: "read", communications: "write", risk: "write" },
  applicant: { leasing: "write", communications: "write" },
};
